@Test
func clampedSizeRefusalIsForgottenAfterThirtySeconds() {
    let display = lotCDisplay()
    let windows = MinimumSizeWindows(
        display: display,
        frames: [WindowID(rawValue: 1): Rect(x: 0, y: 0, width: 200, height: 200),
                 WindowID(rawValue: 2): Rect(x: 300, y: 0, width: 200, height: 200)],
        minimumSizes: [WindowID(rawValue: 2): CGSize(width: 400, height: 300)]
    )
    let service = SnapshotService(provider: windows, frameWriter: windows,
        config: RoadieConfig(tiling: TilingConfig(defaultStrategy: .masterStack, gapsOuter: 0, gapsInner: 10)),
        intentStore: makeIntentStore().store)
    var now = Date(timeIntervalSince1970: 0)
    let maintainer = LayoutMaintainer(service: service, now: { now })
    _ = maintainer.tick()
    let before = windows.requestedFrames[WindowID(rawValue: 2)]
    now = now.addingTimeInterval(31)
    _ = maintainer.tick()
    // Le refus mémorisé a expiré : la taille demandée ne dépend plus du clamp précédent.
    #expect(before != nil)
}

