@Test
func exclusiveLockExcludesSecondHolderUntilReleased() throws {
    let path = uniqueLockPath()
    let holder = FileLock(path: path)
    try holder.acquire(mode: .exclusive)
    let probe = open(path, O_RDWR | O_CREAT, 0o644)
    defer { close(probe) }
    #expect(flock(probe, LOCK_EX | LOCK_NB) != 0)
    holder.release()
    #expect(flock(probe, LOCK_EX | LOCK_NB) == 0)
}

